package sharecore

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sync"
)

var ErrCorrupt = errors.New("block or file SHA-256 mismatch")
var ErrBusy = errors.New("block or stage busy")
var ErrIncomplete = errors.New("stage incomplete")
var ErrUncertain = errors.New("publication started; inspect local destination before any retry")

// Transaction identity binds persisted bytes to a locally approved manifest
// and authenticated remote pin. ID is randomly generated by the controlling
// adapter and never a remote pathname. Spool must be locally audited/private.
type Transaction struct {
	ID Digest
	Peer Digest
	Manifest Digest
}

func (t Transaction) encode()[]byte{
	return []byte(fmt.Sprintf("PST2\n%x\n%x\n%x\n",t.ID,t.Peer,t.Manifest))
}

// Stage holds one explicitly opened transaction. One owner only; do not
// open it concurrently in multiple processes. No peer-controlled spool path.
// Opaque filenames cannot map onto destination relative paths.
type Stage struct{
	scheduleMu sync.Mutex
	mu sync.Mutex
	root string
	tx Transaction
	m Manifest
	budget *Budget
	base []int
	receipt []byte
	inflight map[int]bool
	closed bool
	sealed bool
}

func(s *Stage) Path()string{return s.root}
func(s *Stage) Transaction()Transaction{return s.tx}

func prepare(m Manifest,tx Transaction,b *Budget)([]byte,Manifest,error){
	if b==nil||tx.ID==(Digest{})||tx.Peer==(Digest{}){return nil,Manifest{},errors.New("invalid local transaction")}
	data,err:=m.Encode()
	if err!=nil{return nil,Manifest{},err}
	if sha256.Sum256(data)!=tx.Manifest{return nil,Manifest{},errors.New("manifest identity mismatch")}
	// Deep clone so adapters cannot mutate validated metadata.
	clone,err:=Decode(data)
	return data,clone,err
}

func ordinary(path string,dir bool)(os.FileInfo,error){
	info,err:=os.Lstat(path)
	if err!=nil{return nil,err}
	if !ordinaryInfo(info,dir){return nil,errors.New("unsupported stage entry type")}
	return info,nil
}

func openOrdinary(path string,flags int)(*os.File,error){
	before,err:=ordinary(path,false)
	if err!=nil{return nil,err}
	f,err:=os.OpenFile(path,flags,0)
	if err!=nil{return nil,err}
	info,err:=f.Stat()
	if err!=nil||!ordinaryInfo(info,false)||!os.SameFile(before,info){
		f.Close();return nil,errors.New("stage entry changed")
	}
	return f,nil
}

func createFile(path string,data []byte)error{
	f,err:=os.OpenFile(path,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600)
	if err!=nil{return err}
	n,err:=f.Write(data)
	if err==nil&&n!=len(data){err=io.ErrShortWrite}
	if err==nil{err=f.Sync()}
	return errors.Join(err,f.Close())
}

func readExactFile(path string,n int)([]byte,error){
	f,err:=openOrdinary(path,os.O_RDONLY)
	if err!=nil{return nil,err}
	defer f.Close()
	info,err:=f.Stat()
	if err!=nil{return nil,err}
	if info.Size()!=int64(n){return nil,errors.New("stage metadata length mismatch")}
	data:=make([]byte,n)
	if _,err=io.ReadFull(f,data);err!=nil{return nil,err}
	var extra [1]byte
	if got,err:=f.Read(extra[:]);got!=0||err!=io.EOF{return nil,errors.New("stage metadata changed")}
	return data,nil
}

func newStage(root string,tx Transaction,m Manifest,b *Budget)*Stage{
	s:=&Stage{root:root,tx:tx,m:m,budget:b,inflight:make(map[int]bool)}
	total:=0
	s.base=make([]int,len(m.Entries))
	for i,e:=range m.Entries{s.base[i]=total;total+=len(e.Blocks)}
	s.receipt=make([]byte,total)
	return s
}

func(s *Stage) file(i uint32)string{return filepath.Join(s.root,fmt.Sprintf("file-%08x.part",i))}
func(s *Stage) receiptPath()string{return filepath.Join(s.root,"blocks.v2")}

// Create returns a fresh local transaction directory. On failure the caller
// must inspect the returned path if nonempty; never recursively delete an
// unverified directory or infer ownership from its name.
func Create(parent string,tx Transaction,m Manifest,b *Budget)(stage *Stage,err error){
	if !filepath.IsAbs(parent){return nil,errors.New("absolute private spool required")}
	if _,err:=ordinary(parent,true);err!=nil{return nil,err}
	data,clone,err:=prepare(m,tx,b)
	if err!=nil{return nil,err}
	dir,err:=os.MkdirTemp(parent,"share-v2-")
	if err!=nil{return nil,err}
	s:=newStage(dir,tx,clone,b)
	fail:=func(e error)(*Stage,error){s.closed=true;return s,e}
	if err=createFile(filepath.Join(dir,"transaction.v2"),tx.encode());err!=nil{return fail(err)}
	if err=createFile(filepath.Join(dir,"manifest.v2"),data);err!=nil{return fail(err)}
	if err=createFile(s.receiptPath(),s.receipt);err!=nil{return fail(err)}
	for i,e:=range clone.Entries{
		if e.Directory{continue}
		// Do not preallocate 1 TiB or create remote-named files.
		if err=createFile(s.file(uint32(i)),nil);err!=nil{return fail(err)}
	}
	return s,nil
}

// Reopen is explicit recovery of a locally selected private transaction.
// Never auto-discover or reopen a transaction based on a remote ID alone.
// Validate the exact manifest, identity and recorded blocks before resume.
func Reopen(ctx context.Context,root string,tx Transaction,m Manifest,b *Budget)(*Stage,error){
	if !filepath.IsAbs(root){return nil,errors.New("absolute stage required")}
	if _,err:=ordinary(root,true);err!=nil{return nil,err}
	data,clone,err:=prepare(m,tx,b)
	if err!=nil{return nil,err}
	for name,expect:=range map[string][]byte{"transaction.v2":tx.encode(),"manifest.v2":data}{
		got,err:=readExactFile(filepath.Join(root,name),len(expect))
		if err!=nil{return nil,err}
		if !bytes.Equal(got,expect){return nil,errors.New("recovery identity mismatch")}
	}
	// An interrupted publication never becomes an automatic retry.
	if _,err:=os.Lstat(filepath.Join(root,"publish.v2"));!os.IsNotExist(err){return nil,ErrUncertain}
	s:=newStage(root,tx,clone,b)
	receipt,err:=readExactFile(s.receiptPath(),len(s.receipt))
	if err!=nil{return nil,err}
	copy(s.receipt,receipt)
	for i,e:=range clone.Entries{
		if e.Directory{continue}
		info,err:=ordinary(s.file(uint32(i)),false)
		if err!=nil{return nil,err}
		if info.Size()<0||uint64(info.Size())>e.Size{return nil,errors.New("invalid recovery file size")}
		for j:=range e.Blocks{
			k:=s.base[i]+j
			if s.receipt[k]>1{return nil,errors.New("invalid block receipt")}
			if s.receipt[k]==0{continue}
			if err:=b.run(ctx,func(buf []byte)error{return s.checkBlock(ctx,Block{uint32(i),uint32(j)},buf)});err!=nil{
				if !errors.Is(err,ErrCorrupt)&&!errors.Is(err,io.EOF)&&!errors.Is(err,io.ErrUnexpectedEOF){return nil,err}
				if err=s.mark(k,0);err!=nil{return nil,err}
			}
		}
	}
	return s,nil
}

func(s *Stage) mark(k int,value byte)error{
	f,err:=openOrdinary(s.receiptPath(),os.O_WRONLY)
	if err!=nil{return err}
	info,err:=f.Stat()
	if err==nil&&info.Size()!=int64(len(s.receipt)){err=errors.New("block receipt length changed")}
	if err==nil{var n int;n,err=f.WriteAt([]byte{value},int64(k));if err==nil&&n!=1{err=io.ErrShortWrite}}
	if err==nil{err=f.Sync()}
	err=errors.Join(err,f.Close())
	if err==nil{s.receipt[k]=value}
	return err
}

func(s *Stage) checkBlock(ctx context.Context,block Block,buf []byte)error{
	offset,n,digest,err:=s.m.blockInfo(block)
	if err!=nil{return err}
	f,err:=openOrdinary(s.file(block.File),os.O_RDONLY)
	if err!=nil{return err}
	defer f.Close()
	h:=sha256.New()
	if err=copyExact(ctx,h,io.NewSectionReader(f,offset,int64(n)),int64(n),buf);err!=nil{return err}
	if !bytes.Equal(h.Sum(nil),digest[:]){return ErrCorrupt}
	return nil
}

func(s *Stage) Missing()([]Block,error){
	s.mu.Lock();defer s.mu.Unlock()
	if s.closed||s.sealed{return nil,errors.New("stage closed or sealed")}
	out:=make([]Block,0)
	for i,e:=range s.m.Entries{
		for j:=range e.Blocks{if s.receipt[s.base[i]+j]==0{out=append(out,Block{uint32(i),uint32(j)})}}
	}
	return out,nil
}

// Receive writes an exact logical block using bounded streaming memory.
// Data is synced before its durable receipt. Duplicate/in-flight writes are
// rejected. Failed bytes never become a verified block; they may be retried.
func(s *Stage) Receive(ctx context.Context,block Block,r io.Reader)error{
	return s.budget.run(ctx,func(buf []byte)error{
		return s.receive(ctx,block,r,buf,nil)
	})
}

func(s *Stage) receive(ctx context.Context,block Block,r io.Reader,buf []byte,finished func()error)error{
	offset,n,digest,err:=s.m.blockInfo(block)
	if err!=nil||r==nil{return errors.New("invalid block request")}
	k:=s.base[block.File]+int(block.Index)
	s.mu.Lock()
	if s.closed||s.sealed||s.inflight[k]||s.receipt[k]!=0{s.mu.Unlock();return ErrBusy}
	s.inflight[k]=true;s.mu.Unlock()
	defer func(){s.mu.Lock();delete(s.inflight,k);s.mu.Unlock()}()
	f,err:=openOrdinary(s.file(block.File),os.O_WRONLY)
	if err!=nil{return err}
	h:=sha256.New()
	err=copyExact(ctx,io.MultiWriter(io.NewOffsetWriter(f,offset),h),r,int64(n),buf)
	if err==nil&&!bytes.Equal(h.Sum(nil),digest[:]){err=ErrCorrupt}
	if err==nil&&finished!=nil{err=finished()}
	if err==nil{err=f.Sync()}
	err=errors.Join(err,f.Close())
	if err!=nil{return err}
	s.mu.Lock();defer s.mu.Unlock()
	return s.mark(k,1)
}

// Seal verifies the entire file independently of the per-block receipts,
// then creates an exclusive publication marker BEFORE calling the reviewed
// local publisher. A publisher must independently check the bytes on its
// opened handles and never replace an existing destination. The callback
// gets only local opaque paths + manifest metadata; no remote absolute paths.
// A failed or interrupted publication remains uncertain, never auto-retried.
// Empty directories are represented by metadata; the publisher owns creation.
type Publisher func(context.Context,Entry,string)error

func(s *Stage) Seal(ctx context.Context,publish Publisher)error{
	if publish==nil{return errors.New("reviewed local publisher required")}
	s.mu.Lock()
	if s.closed||s.sealed||len(s.inflight)!=0{s.mu.Unlock();return ErrBusy}
	for _,v:=range s.receipt{if v!=1{s.mu.Unlock();return ErrIncomplete}}
	s.sealed=true;s.mu.Unlock()
	// No further writes are accepted even if verification fails; explicitly
	// reopen and revalidate a failed verification, not a publication attempt.
	for i,e:=range s.m.Entries{
		if e.Directory{continue}
		err:=s.budget.run(ctx,func(buf []byte)error{
			f,err:=openOrdinary(s.file(uint32(i)),os.O_RDONLY)
			if err!=nil{return err}
			defer f.Close()
			info,err:=f.Stat()
			if err!=nil{return err}
			if info.Size()!=int64(e.Size){return ErrCorrupt}
			h:=sha256.New()
			if err=copyExact(ctx,h,f,int64(e.Size),buf);err!=nil{return err}
			if !bytes.Equal(h.Sum(nil),e.Hash[:]){return ErrCorrupt}
			return nil
		})
		if err!=nil{return err}
	}
	if err:=ctx.Err();err!=nil{return err}
	if err:=createFile(filepath.Join(s.root,"publish.v2"),[]byte("publishing\n"));err!=nil{return errors.Join(ErrUncertain,err)}
	for i,e:=range s.m.Entries{
		if err:=ctx.Err();err!=nil{return errors.Join(ErrUncertain,err)}
		path:=""
		if !e.Directory{path=s.file(uint32(i))}
		e.Blocks=append([]Digest(nil),e.Blocks...)
		if err:=publish(ctx,e,path);err!=nil{return errors.Join(ErrUncertain,err)}
	}
	if err:=createFile(filepath.Join(s.root,"published.v2"),[]byte("published\n"));err!=nil{return errors.Join(ErrUncertain,err)}
	return nil
}

func(s *Stage) Close()error{
	s.mu.Lock();defer s.mu.Unlock()
	if len(s.inflight)!=0{return ErrBusy}
	s.closed=true
	return nil
}

// ParseLocalID is for local receipt/diagnostic adapters, not authorization.
func ParseLocalID(text string)(Digest,error){
	var out Digest
	if len(text)!=64{return out,errors.New("invalid transaction identity")}
	data,err:=hex.DecodeString(text)
	if err!=nil{return out,err}
	copy(out[:],data);return out,nil
}

// VerifiedBytes is a monotonic, bounded local receipt counter.
func(s *Stage) VerifiedBytes()uint64{
	s.mu.Lock();defer s.mu.Unlock()
	var total uint64
	for i,e:=range s.m.Entries{
		for j:=range e.Blocks{if s.receipt[s.base[i]+j]==1{
			total+=min(uint64(BlockSize),e.Size-uint64(j)*BlockSize)
		}}
	}
	return total
}

// LocalStageID reads only a locally selected stage; Reopen subsequently
// verifies the complete transaction identity, manifest and receipts.
func LocalStageID(root string)(Digest,error){
	if _,err:=ordinary(root,true);err!=nil{return Digest{},err}
	data,err:=readExactFile(filepath.Join(root,"transaction.v2"),5+65*3)
	if err!=nil{return Digest{},err}
	if string(data[:5])!="PST2\n"||data[69]!='\n'||data[134]!='\n'||data[199]!='\n'{return Digest{},errors.New("invalid stage metadata")}
	return ParseLocalID(string(data[5:69]))
}

// Release known payloads only after successful publication; keep the small
// manifest/receipt/terminal markers as durable recovery/history evidence.
func(s *Stage) ClearPublishedPayloads()error{
	s.mu.Lock();defer s.mu.Unlock()
	if !s.sealed||len(s.inflight)!=0{return ErrBusy}
	data,err:=readExactFile(filepath.Join(s.root,"published.v2"),len("published\n"))
	if err!=nil||string(data)!="published\n"{return ErrUncertain}
	var result error
	for i,e:=range s.m.Entries{
		if e.Directory{continue}
		path:=s.file(uint32(i))
		if _,err:=ordinary(path,false);os.IsNotExist(err){continue}else if err!=nil{result=errors.Join(result,err);continue}
		result=errors.Join(result,os.Remove(path))
	}
	return result
}
